        let (t15, t16) = t13.subtractingReportingOverflow(t12)
        let t17: UInt64 = (t14 ? 1 : 0) &+ (t16 ? 1 : 0)
        let t18 = (0xBFD2_5E8C_D036_4141 & (0 &- t17)) | (0 & ~(0 &- t17))
        let t19 = (0xBAAE_DCE6_AF48_A03B & (0 &- t17)) | (0 & ~(0 &- t17))
        let t20 = (0xFFFF_FFFF_FFFF_FFFE & (0 &- t17)) | (0 & ~(0 &- t17))
        let t21 = (0xFFFF_FFFF_FFFF_FFFF & (0 &- t17)) | (0 & ~(0 &- t17))
        let (t22, t23) = t0.addingReportingOverflow(t18)
        let t24: UInt64 = t23 ? 1 : 0
        let (t25, t26) = t5.addingReportingOverflow(t19)
        let (t27, t28) = t25.addingReportingOverflow(t24)
        let t29: UInt64 = (t26 ? 1 : 0) &+ (t28 ? 1 : 0)
        let (t30, t31) = t10.addingReportingOverflow(t20)
        let (t32, t33) = t30.addingReportingOverflow(t29)
        let t34: UInt64 = (t31 ? 1 : 0) &+ (t33 ? 1 : 0)
        let (t35, _) = t15.addingReportingOverflow(t21)
        let (t37, _) = t35.addingReportingOverflow(t34)
        return Integer256(l0: t22, l1: t27, l2: t32, l3: t37)
    }

    /// Any 256-bit a modulo n (`Scalar.canonical_spec`).
    static func reduce(_ a: Integer256) -> Integer256 {
        let (t0, t1) = a.l0.addingReportingOverflow(0x402D_A173_2FC9_BEBF)
        let t2: UInt64 = t1 ? 1 : 0
        let (t3, t4) = a.l1.addingReportingOverflow(0x4551_2319_50B7_5FC4)
        let (t5, t6) = t3.addingReportingOverflow(t2)
        let t7: UInt64 = (t4 ? 1 : 0) &+ (t6 ? 1 : 0)
        let (t8, t9) = a.l2.addingReportingOverflow(1)
        let (t10, t11) = t8.addingReportingOverflow(t7)
        let t12: UInt64 = (t9 ? 1 : 0) &+ (t11 ? 1 : 0)
        let (t13, t14) = a.l3.addingReportingOverflow(0)
        let (t15, t16) = t13.addingReportingOverflow(t12)
        let t17: UInt64 = (t14 ? 1 : 0) &+ (t16 ? 1 : 0)
        let t18 = (t0 & (0 &- t17)) | (a.l0 & ~(0 &- t17))
        let t19 = (t5 & (0 &- t17)) | (a.l1 & ~(0 &- t17))
        let t20 = (t10 & (0 &- t17)) | (a.l2 & ~(0 &- t17))
        let t21 = (t15 & (0 &- t17)) | (a.l3 & ~(0 &- t17))
        return Integer256(l0: t18, l1: t19, l2: t20, l3: t21)
    }
}
